import type { MetadataRoute } from "next";

// Web app manifest: makes WebDrop installable (Android/desktop "Install app",
// iOS "Add to Home Screen"). Icons reference the PNGs generated by
// scripts/generate-pwa-icons.mjs from the wordmark's signal-wave logo mark.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "WebDrop — Instant File Transfer",
    short_name: "WebDrop",
    description:
      "Instantly transfer files, photos, videos, and text between any two devices — no login, no cable, no shared WiFi.",
    start_url: "/",
    display: "standalone",
    background_color: "#0A0E1A",
    theme_color: "#0A0E1A",
    icons: [
      {
        src: "/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon-maskable-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "maskable",
      },
      {
        src: "/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
